        new LocalisedText("You are not currently in a clan channel.", "Du befindest dich derzeit nicht in einem Chatraum.", "Vous n'\u00eates pas dans un canal de clan.", "No momento voc\u00ea n\u00e3o est\u00e1 em um canal de cl\u00e3.");
